@dataclass(frozen=True)
class Command:
    """One row of the palette. It runs `event` (a State event and its arguments), or `press`
    (a shortcut handled in the browser, run as if its key were pressed where you were).
    """

    id: str
    """Stable name: what "recently used" remembers (assets/panes.js)."""
    group: str
    """Shown before the title, eg "View", so typing a group lists its commands."""
    title: str
    icon: str
    event: tuple[str, ...] = ()
    """A State event's name, then its arguments, eg ("toggle_pane", "python")."""
    press: Shortcut | None = None
    shortcut: Shortcut | None = None
    """Shown on the right of the row (default: `press`)."""
    shown: str = ""
    """A State bool: the title gets "Hide" / "Show" before it, by whether that is on."""
    words: str = ""
    """Other words that find it when typed."""
    slash: str = ""
    """Its slash command, without the slash (eg "clear-chat":
    typed as /clear-chat in the chat box).
    Lower-case words joined by "-". "" = palette only."""
    takes: str = ""
    """What the text after the slash command is, shown
    in the list as "/<slash> <takes>". "" = it
    takes none (text after it is refused, so a sentence
    that only starts with it runs nothing)."""
    slash_event: tuple[str, ...] = ()
    """The State event the slash command runs instead of the palette row's, with its arguments;
    the text after the command is added as the last one ("" when none). For a command whose
    output belongs in the chat, eg a widget shown under
    the command. () = the palette's event."""

    def __post_init__(self) -> None:
        if bool(self.event) == bool(self.press):
            raise ValueError(f"command {self.id!r}: give exactly one of `event` and `press`")
        if self.slash and not re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", self.slash):
            raise ValueError(f"command {self.id!r}: slash {self.slash!r} must be lower-case words joined by '-'")
        if (self.takes and not self.slash_event) or (self.slash_event and not self.slash):
            raise ValueError(f"command {self.id!r}: `takes` needs a `slash_event`, on a slash command")

    @property
    def keys(self) -> str:
        shortcut = self.shortcut or self.press
        return shortcut.keys if shortcut else ""


